type User={id:string;nome:string;email:string;papel:string};
const enc=new TextEncoder();
function b64url(bytes:Uint8Array){return btoa(String.fromCharCode(...bytes)).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"")}
async function deriveLoginProof(password:string,salt:string,iterations:number){const key=await crypto.subtle.importKey("raw",enc.encode(password),"PBKDF2",false,["deriveBits"]);const bits=await crypto.subtle.deriveBits({name:"PBKDF2",hash:"SHA-256",salt:Uint8Array.from(atob(salt.replace(/-/g,"+").replace(/_/g,"/")+"===".slice((salt.length+3)%4)),c=>c.charCodeAt(0)),iterations},key,256);return b64url(new Uint8Array(bits))}
async function challengeProof(digest:string,nonce:string){const raw=Uint8Array.from(atob(digest.replace(/-/g,"+").replace(/_/g,"/")+"===".slice((digest.length+3)%4)),c=>c.charCodeAt(0));const key=await crypto.subtle.importKey("raw",raw,{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64url(new Uint8Array(await crypto.subtle.sign("HMAC",key,enc.encode(nonce))))}
async function api(path:string,body?:unknown,token?:string,httpMethod?:string){const headers:Record<string,string>={};if(body)headers["Content-Type"]="application/json";if(token)headers["Authorization"]="Bearer "+token;const r=await fetch(API+path,{method:httpMethod??(body?"POST":"GET"),credentials:"include",headers:Object.keys(headers).length?headers:undefined,body:body?JSON.stringify(body):undefined});const data=await r.json().catch(()=>({error:"Resposta inválida do servidor"}));if(!r.ok)throw new Error(data.reference?`${data.error||"Falha na solicitação"} (${data.reference})`:data.error||"Não foi possível concluir a solicitação");return data}

function money(cents:number){return new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format((Number(cents)||0)/100)}
function dateLabel(value:string){if(!value)return "";const d=new Date(value.length===16?value+":00":value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat("pt-BR",{dateStyle:"short",timeStyle:"short"}).format(d)}
function localDateKey(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,"0"),String(d.getDate()).padStart(2,"0")].join("-")}
function statusLabel(value:string){return ({agendado:"Agendado",em_andamento:"Em andamento",concluido:"Concluído",cancelado:"Cancelado"} as Record<string,string>)[value]??value}
function optimizeVehiclePhoto(file:File):Promise<string>{return new Promise((resolve,reject)=>{if(!file.type.startsWith("image/")){reject(new Error("Escolha uma imagem válida."));return}const reader=new FileReader();reader.onerror=()=>reject(new Error("Não foi possível ler a foto."));reader.onload=()=>{const image=new Image();image.onerror=()=>reject(new Error("Não foi possível abrir a foto."));image.onload=()=>{const max=1400,scale=Math.min(1,max/Math.max(image.width,image.height)),canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext("2d");if(!ctx){reject(new Error("Não foi possível preparar a foto."));return}ctx.drawImage(image,0,0,canvas.width,canvas.height);const data=canvas.toDataURL("image/jpeg",.76);if(data.length>480000){reject(new Error("A foto ficou muito grande. Escolha outra imagem."));return}resolve(data)};image.src=String(reader.result)};reader.readAsDataURL(file)})}
function FluxoBrand({large=false}:{large?:boolean}){return <div className={"brand "+(large?"auth-brand":"")}><span className="brand-symbol" aria-hidden="true"><svg viewBox="0 0 48 48"><path d="M9 11h30v7H17v6h18v7H17v8H9z" fill="currentColor"/><path d="M29 24h10v15H29z" fill="currentColor" opacity=".55"/></svg></span><span className="brand-word"><strong>FLUXO</strong><small>ESTÉTICA AUTOMOTIVA</small></span></div>}
