 const[active,setActive]=useState("Painel"),[open,setOpen]=useState(false),[user,setUser]=useState<User|null>(null),[mode,setMode]=useState<"login"|"setup">("login"),[loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(""),[showPass,setShowPass]=useState(false);
 const[email,setEmail]=useState("gabrielzojota@gmail.com"),[senha,setSenha]=useState(""),[nome,setNome]=useState("Gabriel"),[confirm,setConfirm]=useState(""),[bootstrap,setBootstrap]=useState("");
 const[dashboard,setDashboard]=useState<any>(null),[clients,setClients]=useState<any[]>([]),[services,setServices]=useState<any[]>([]),[appointments,setAppointments]=useState<any[]>([]),[finance,setFinance]=useState<any>({pagamentos:[],em_aberto:[],totais:{}});
 const[clientProfile,setClientProfile]=useState<any|null>(null),[profileLoading,setProfileLoading]=useState(false),[paymentAppointment,setPaymentAppointment]=useState(""),[paymentAmount,setPaymentAmount]=useState(""),[paymentMethod,setPaymentMethod]=useState("pix");
