 const[appointmentClient,setAppointmentClient]=useState(""),[appointmentService,setAppointmentService]=useState(""),[appointmentDate,setAppointmentDate]=useState(()=>{const d=new Date(Date.now()-new Date().getTimezoneOffset()*60000);return d.toISOString().slice(0,16)}),[vehicleModel,setVehicleModel]=useState(""),[vehiclePlate,setVehiclePlate]=useState(""),[appointmentNotes,setAppointmentNotes]=useState("");

 useEffect(()=>{api("/api/auth/me").then(x=>setUser(x.user)).catch(()=>setUser(null)).finally(()=>setLoading(false))},[]);
 async function refreshData(){try{const [d,cl,se,at,ve,fi,st,ex]=await Promise.all([api("/api/dashboard"),api("/api/clientes?q="+encodeURIComponent(search)),api("/api/servicos"),api("/api/atendimentos"),api("/api/veiculos"),api("/api/financeiro"),api("/api/estoque"),api("/api/despesas")]);setDashboard(d);setClients(cl.clientes??[]);setServices(se.servicos??[]);setAppointments(at.atendimentos??[]);setVehicles(ve.veiculos??[]);setFinance(fi);setStock(st);setExpenses(ex.despesas??[]);if(!movementProduct&&st.produtos?.[0])setMovementProduct(st.produtos[0].id);if(!appointmentClient&&cl.clientes?.[0])setAppointmentClient(cl.clientes[0].id);if(!appointmentService&&se.servicos?.[0])setAppointmentService(se.servicos[0].id);setPageError("")}catch(e){setPageError(e instanceof Error?e.message:"Não foi possível carregar os dados.")}}
 useEffect(()=>{if(user)refreshData()},[user,search]);
 async function openClient(id:string){setProfileLoading(true);setPageError("");try{setClientProfile(await api("/api/clientes/"+id))}catch(x){setPageError(x instanceof Error?x.message:"Não foi possível abrir a ficha do cliente")}finally{setProfileLoading(false)}}
 async function createPayment(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/pagamentos",{atendimento_id:paymentAppointment,valor_reais:Number(paymentAmount),metodo:paymentMethod.startsWith("cartao_")?"cartao":paymentMethod,modalidade:paymentMethod.startsWith("cartao_")?paymentMethod.slice(7):"nao_aplicavel"});setPaymentAppointment("");setPaymentAmount("");await refreshData()}catch(x){setPageError(x instanceof Error?x.message:"Falha ao registrar pagamento")}finally{setSaving(false)}}
 async function confirmPayment(id:string){setSaving(true);setPageError("");try{await api("/api/pagamentos/"+id,{status:"recebido"},undefined,"PATCH");await refreshData();if(clientProfile)await openClient(clientProfile.cliente.id)}catch(x){setPageError(x instanceof Error?x.message:"Falha ao confirmar pagamento")}finally{setSaving(false)}}
 async function createClient(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/clientes",{nome:clientName,telefone:clientPhone,email:clientEmail});setClientName("");setClientPhone("");setClientEmail("");await refreshData()}catch(x){setPageError(x instanceof Error?x.message:"Falha ao cadastrar cliente")}finally{setSaving(false)}}
 async function createVehicle(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/veiculos",{cliente_id:vehicleClient,modelo:newVehicleModel,placa:newVehiclePlate,ano:newVehicleYear?Number(newVehicleYear):null,cor:newVehicleColor,foto_data:vehiclePhoto||null});setNewVehicleModel("");setNewVehiclePlate("");setNewVehicleYear("");setNewVehicleColor("");setVehiclePhoto("");await refreshData();if(clientProfile)await openClient(clientProfile.cliente.id)}catch(x){setPageError(x instanceof Error?x.message:"Falha ao cadastrar veículo")}finally{setSaving(false)}}
 async function uploadVehiclePhoto(id:string,file:File){setSaving(true);setPageError("");try{const foto_data=await optimizeVehiclePhoto(file);await api("/api/veiculos/"+id,{foto_data},undefined,"PATCH");await refreshData();if(clientProfile)await openClient(clientProfile.cliente.id);if(vehicleDetail)setVehicleDetail({...vehicleDetail,foto_data})}catch(x){setPageError(x instanceof Error?x.message:"Falha ao salvar a foto")}finally{setSaving(false)}}

 async function createProduct(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/estoque/produtos",{nome:productName,unidade:productUnit,estoque_minimo:Number(productMinimum||0),custo_unitario_reais:Number(productCost||0)});setProductName("");setProductMinimum("0");setProductCost("");await refreshData()}catch(x){setPageError(x instanceof Error?x.message:"Falha ao cadastrar produto")}finally{setSaving(false)}}
 async function createStockMovement(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/estoque/movimentacoes",{produto_id:movementProduct,tipo:movementType,quantidade:Number(movementQuantity),custo_unitario_reais:movementType==="compra"&&movementCost!==""?Number(movementCost):null,motivo:movementReason});setMovementQuantity("");setMovementCost("");setMovementReason("");await refreshData()}catch(x){setPageError(x instanceof Error?x.message:"Falha ao registrar movimentação")}finally{setSaving(false)}}
 async function createExpense(e:FormEvent){e.preventDefault();setSaving(true);setPageError("");try{await api("/api/despesas",{categoria:expenseCategory,descricao:expenseDescription,valor_reais:Number(expenseAmount),vencimento:expenseDueDate||null});setExpenseDescription("");setExpenseAmount("");setExpenseDueDate("");await refreshData()}catch(x){setPageError(x instanceof Error?x.message:"Falha ao cadastrar despesa")}finally{setSaving(false)}}
