 async function login(e:FormEvent){e.preventDefault();setBusy(true);setError("");try{const info=await api("/api/auth/login-info?email="+encodeURIComponent(email));const digest=await deriveLoginProof(senha,info.salt,info.iterations);const proof=await challengeProof(digest,info.nonce);const x=await api("/api/auth/login",{email,nonce:info.nonce,proof});setUser(x.user);setSenha("")}catch(x){setError(x instanceof Error?x.message:"Falha no login")}finally{setBusy(false)}}
 async function setup(e:React.FormEvent){e.preventDefault();setError("");if(senha.length<8){setError("A senha precisa ter pelo menos 8 caracteres.");return}if(senha!==confirm){setError("As senhas não conferem.");return}setBusy(true);try{const salt=b64url(crypto.getRandomValues(new Uint8Array(16)));const senha_hash=await deriveLoginProof(senha,salt,100000);await api("/api/auth/setup-owners",{owners:[{nome,email,senha_hash,salt}]},bootstrap);setError("Configuração enviada. Se o código de configuração estiver correto, você poderá entrar.");setMode("login");setSenha("");setConfirm("");}catch(x){setError(x instanceof Error?x.message:"Falha na configuração")}finally{setBusy(false)}}
